begin;
create or replace function public.get_admin_activity(p_limit integer default 200) returns table(id bigint,admin_id uuid,admin_name text,admin_role text,activity_type text,page_path text,device_info text,latitude numeric,longitude numeric,accuracy_m numeric,created_at timestamptz) language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from customers c where c.id=auth.uid() and c.is_admin=true and coalesce(c.blocked,false)=false and coalesce(c.admin_role,'admin') in ('admin','developer_admin')) then raise exception '관리자 이상만 활동기록을 볼 수 있습니다.';end if;return query select e.id,e.admin_id,coalesce(c.business_name,c.owner_name,c.email,'관리자')::text,coalesce(c.admin_role,'admin')::text,e.activity_type,e.page_path,e.device_info,e.latitude,e.longitude,e.accuracy_m,e.created_at from admin_activity_events e join customers c on c.id=e.admin_id order by e.created_at desc limit greatest(1,least(coalesce(p_limit,200),1000));end;$$;
revoke all on function public.get_admin_activity(integer) from public;grant execute on function public.get_admin_activity(integer) to authenticated;
commit;
